import { Image, StyleSheet, View, type ImageRequireSource, type StyleProp, type ViewStyle } from 'react-native';
import { useTheme } from '../theme/ThemeProvider';
import { cornerStyle, HIDDEN, PASS_THROUGH, type Corners } from './paint';

// The 256px tile of DIRECTION-A §12, generated by scripts/gen-grain.mjs (see assets/textures/README.md).
// eslint-disable-next-line @typescript-eslint/no-require-imports -- Metro resolves static assets only through require()
export const GRAIN_TILE: ImageRequireSource = require('../../assets/textures/grain-256.png');

export type GrainProps = {
  /** Rendered opacity: glass.grain.ground (0.064), .card (0.056) or .lens (0.128). */
  opacity: number;
  /** Clip to the parent's corner radius when the parent does not clip. */
  radius?: number;
  corners?: Corners;
  style?: StyleProp<ViewStyle>;
};

/**
 * Pre-tinted grain, normal blend, repeated over the parent (absolute fill, never takes touches).
 * Light theme draws nothing: grain is part of the Lens glass only.
 */
export function Grain({ opacity, radius, corners = 'all', style }: GrainProps) {
  const { glass } = useTheme();
  if (!glass.enabled || opacity <= 0) return null;
  return (
    <View {...HIDDEN} style={[StyleSheet.absoluteFill, PASS_THROUGH, radius ? [cornerStyle(radius, corners), styles.clip] : null, { opacity }, style]}>
      <Image source={GRAIN_TILE} resizeMode="repeat" style={styles.fill} />
    </View>
  );
}

const styles = StyleSheet.create({
  clip: { overflow: 'hidden' },
  fill: { width: '100%', height: '100%' },
});
